}

// Ative para controlar o bot por código.
function start() { engine.bot(self.id, "attack"); }
function update(dt, time, input) {
  if (input.pressed.b) engine.bot(self.id, "follow");
  if (input.pressed.n) engine.bot(self.id, "patrol");
  if (input.pressed.k) engine.damage(self.id, 100);
